:root{color-scheme:light;--oc-ink:#163D32;--oc-paper:#F5F7F4;--oc-accent:#D5E8A0;--oc-soft:#ECF1E8;--oc-muted:#61716A;--oc-line:#DDE5DC}
*{box-sizing:border-box}body{margin:0}a{color:inherit}button,input{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a,button,input{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #789B40;outline-offset:4px}
.oc-auth-page{font:15px/1.6 "Segoe UI",Arial,sans-serif;background:var(--oc-paper);color:var(--oc-ink);min-height:100vh;-webkit-font-smoothing:antialiased}
.oc-icon{width:20px;height:20px;display:inline-block;flex:none;vertical-align:middle;fill:none;stroke:currentColor;stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}.oc-icon-back{transform:rotate(180deg)}
.oc-auth-header{max-width:1240px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:28px 40px}
.oc-brand{display:inline-flex;align-items:center;gap:10px;font-size:23px;font-weight:700;letter-spacing:-1px;text-decoration:none;line-height:1.2}.oc-brand img{display:block;width:36px;height:36px;border-radius:9px}.oc-brand span{color:var(--oc-ink)}
.oc-back{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;text-decoration:none;color:var(--oc-muted)}.oc-back .oc-icon{width:17px;height:17px}.oc-back:hover{color:var(--oc-ink)}
.oc-auth-layout{max-width:1160px;margin:auto;padding:58px 40px 72px;display:grid;grid-template-columns:1.04fr 1fr;gap:86px;align-items:center}
.oc-eyebrow{text-transform:uppercase;letter-spacing:1.6px;font-size:10px;font-weight:700;color:var(--oc-muted);margin:0 0 18px}
.oc-auth-story h1{font-size:clamp(36px,4vw,49px);line-height:1.1;letter-spacing:-1.8px;font-weight:650;margin:0 0 22px}
.oc-auth-story>p:not(.oc-eyebrow){font-size:15px;color:var(--oc-muted);max-width:390px;line-height:1.8;margin:0}
.oc-recipe-note{background:#fff;border:1px solid var(--oc-line);border-radius:14px;padding:22px;margin:30px 0 24px;max-width:430px;box-shadow:0 8px 24px #163D3204}
.oc-note-label{font-size:10px;font-weight:600;color:var(--oc-muted)}
.oc-note-dish{display:flex;align-items:center;gap:12px;margin:17px 0}.oc-dish-icon{display:grid;place-items:center;width:46px;height:46px;background:var(--oc-soft);border-radius:11px;flex:none}.oc-dish-icon .oc-icon{width:26px;height:26px}.oc-note-dish strong{display:block;font-size:15px;font-weight:650;letter-spacing:-.2px}.oc-note-dish div>span{display:block;font-size:11px;color:var(--oc-muted);margin-top:2px}
.oc-note-stats{display:flex;align-items:center;gap:27px;padding:16px 0;border-top:1px solid var(--oc-line);border-bottom:1px solid var(--oc-line)}.oc-note-stats>div{display:flex;flex-direction:column;gap:1px}.oc-note-stats strong{font-size:26px;line-height:1.2;font-weight:650;letter-spacing:-.8px;font-variant-numeric:tabular-nums}.oc-note-stats span{font-size:10px;color:var(--oc-muted)}.oc-note-stats .oc-note-linked{margin-left:auto;align-items:flex-end;gap:6px}.oc-note-linked .oc-icon{width:20px;height:20px;color:#426743}
.oc-note-flow{display:flex;align-items:center;gap:15px;padding-top:15px;font-size:11px;font-weight:600}.oc-note-flow .oc-icon{width:15px;height:15px;color:#819188}
.oc-assurances{padding:0;list-style:none;color:var(--oc-muted);font-size:11px;display:grid;gap:7px;margin:0}.oc-assurances li{display:flex;gap:8px;align-items:center}.oc-assurances .oc-icon{width:15px;height:15px;color:#517644}
.oc-login-card{border:1px solid var(--oc-line);border-radius:18px;background:white;padding:34px;box-shadow:0 12px 44px #163D3205;min-width:0}
.oc-badge{display:inline-flex;align-items:center;gap:6px;border-radius:6px;background:var(--oc-soft);color:#3F6244;font-size:10px;font-weight:600;padding:5px 9px;margin-bottom:21px}.oc-badge .oc-icon{width:13px;height:13px}
.oc-login-card h2{font-size:27px;line-height:1.25;letter-spacing:-.9px;font-weight:650;margin:0 0 9px}.oc-card-intro{font-size:12px;color:var(--oc-muted);margin:0 0 23px;line-height:1.7}
.oc-login-form{display:grid;gap:8px}.oc-login-form>label{font-size:12px;font-weight:600;margin-top:8px}.oc-login-form input:not([type=hidden]){width:100%;border:1px solid #CDD8CE;border-radius:7px;background:#FDFEFC;min-height:48px;padding:11px 13px;color:var(--oc-ink);font-size:14px;min-width:0}.oc-login-form input::placeholder{color:#819088}.oc-login-form input:focus{border-color:#739078}.oc-password-field{position:relative}.oc-password-field input{padding-right:80px!important}.oc-password-field button{position:absolute;right:6px;top:5px;bottom:5px;padding:5px 8px;background:transparent;border:0;border-radius:4px;color:var(--oc-muted);font-size:11px;font-weight:600}.oc-password-field button:hover{background:var(--oc-soft)}
.oc-primary{border:1px solid var(--oc-ink);background:var(--oc-ink);color:#fff;min-height:48px;border-radius:7px;padding:12px 15px;display:flex;align-items:center;justify-content:space-between;gap:16px;font-size:12px;font-weight:600;text-decoration:none;text-align:center;margin-top:16px}.oc-primary:hover{background:#254F40;border-color:#254F40}.oc-primary .oc-icon{width:18px;height:18px}
.oc-small-print{font-size:10px;line-height:1.8;color:var(--oc-muted);margin:21px 0 0}.oc-small-print a{white-space:nowrap;text-underline-offset:3px}
.oc-auth-footer{max-width:1160px;margin:auto;padding:0 40px 28px;display:flex;justify-content:space-between;gap:16px;color:var(--oc-muted);font-size:10px}.oc-auth-footer a{text-decoration:none}.oc-auth-footer a:hover{text-decoration:underline}
.oc-notice{background:var(--oc-soft);border:1px solid #D9E3CD;border-radius:7px;padding:12px;margin:15px 0;font-size:12px;line-height:1.6}.oc-error{color:#873E2E;background:#FFF3EE;border-color:#EDCDBF}
.oc-skip,.oc-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.oc-skip:focus{clip-path:none;width:auto;height:auto;z-index:100;left:20px;top:12px;background:white;padding:10px 16px}
.oc-message-page{display:grid;place-items:center;padding:40px 22px}.oc-message-card{max-width:480px;width:100%;display:grid;gap:20px}.oc-message-card .oc-badge{margin:12px 0 -6px;justify-self:start}.oc-message-card h1{font-size:32px;line-height:1.18;letter-spacing:-1px;margin:0}.oc-message-card p{font-size:13px;color:var(--oc-muted);margin:0}.oc-message-card .oc-primary{margin:0}.oc-message-card>.oc-back{justify-content:center}
.oc-privacy{max-width:900px;margin:28px auto 70px;padding:0 40px}.oc-privacy-hero{max-width:690px;padding:16px 0 30px}.oc-privacy h1{font-size:42px;line-height:1.13;letter-spacing:-1.5px;font-weight:650;margin:0 0 22px}.oc-privacy .oc-eyebrow{font-size:10px;line-height:1.5;margin-bottom:18px}.oc-privacy h2{font-size:18px;line-height:1.35;letter-spacing:-.35px;font-weight:650;margin:30px 0 10px}.oc-privacy h2:first-child{margin-top:0}.oc-privacy p,.oc-privacy li{font-size:13px;color:var(--oc-muted);line-height:1.85}.oc-privacy p{margin:0 0 15px}.oc-privacy p:last-child{margin-bottom:0}.oc-privacy ul{padding-left:20px}.oc-privacy strong{color:var(--oc-ink);font-weight:600}.oc-privacy code{font-size:11px;overflow-wrap:anywhere;background:var(--oc-paper);border-radius:4px;padding:2px 4px}.oc-privacy-body{padding:32px 36px;border:1px solid var(--oc-line);background:#fff;border-radius:16px}.oc-privacy-highlights{display:flex;gap:16px;flex-wrap:wrap;margin:22px 0 0;padding:0!important;list-style:none}.oc-privacy-highlights li{display:inline-flex;align-items:center;gap:6px;font-size:10px;font-weight:600}.oc-privacy-highlights .oc-icon{width:16px;height:16px;color:#517644}.oc-privacy-link{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;text-decoration:none;margin-top:18px}.oc-privacy-link:hover{text-decoration:underline}
@media(max-width:940px){.oc-auth-layout{gap:40px;padding-top:32px}.oc-auth-story h1{font-size:40px}.oc-login-card{padding:28px}.oc-note-stats{gap:20px}.oc-note-linked span{max-width:75px;text-align:right}.oc-recipe-note{padding:20px}}
@media(max-width:700px){.oc-auth-header{padding:22px;gap:18px}.oc-brand{font-size:21px;gap:8px}.oc-brand img{width:32px;height:32px;border-radius:8px}.oc-back{font-size:10px;gap:5px}.oc-back .oc-icon{width:15px;height:15px}.oc-auth-layout{padding:25px 22px 36px;grid-template-columns:1fr;gap:28px;max-width:540px}.oc-auth-story h1{font-size:36px;letter-spacing:-1.3px;margin-bottom:15px}.oc-auth-story>p:not(.oc-eyebrow){font-size:13px;max-width:none}.oc-auth-story .oc-eyebrow{font-size:9px;margin-bottom:14px}.oc-recipe-note,.oc-assurances{display:none}.oc-login-card{padding:26px 22px;border-radius:14px}.oc-login-card h2{font-size:25px}.oc-login-form input:not([type=hidden]){font-size:16px}.oc-badge{margin-bottom:18px}.oc-auth-footer{padding:0 22px 26px;flex-wrap:wrap;font-size:10px;max-width:540px}.oc-privacy{margin:15px auto 40px;padding:0 22px}.oc-privacy-hero{padding-top:10px;padding-bottom:24px}.oc-privacy h1{font-size:34px;letter-spacing:-1.1px}.oc-privacy-body{padding:25px 22px;border-radius:14px}.oc-privacy-highlights{display:grid;gap:8px}.oc-privacy h2{font-size:17px}.oc-message-card h1{font-size:29px}}
@media(max-width:370px){.oc-auth-header{padding:18px}.oc-brand{font-size:19px}.oc-back{max-width:120px}.oc-auth-layout{padding-left:18px;padding-right:18px}.oc-note-flow{gap:10px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

/* Shared compact language choice for sign-in and privacy pages. */
.oc-auth-actions{display:flex;align-items:center;justify-content:flex-end;gap:22px;min-width:0}
