@media(max-width:640px){.site-navigation{top:70px;padding-inline:18px}.founder-grid{grid-template-columns:1fr 1fr;gap:10px}.founder-card{padding:14px 12px;flex-direction:column;align-items:flex-start;gap:9px}.founder-card h3{font-size:14px}.language-switch a{min-height:34px;min-width:30px;padding-inline:4px}.header-inner{gap:10px}}
@media(max-width:380px){.header-inner{gap:7px}.header-inner .brand{font-size:20px;gap:6px}.header-inner .brand>img{width:28px;height:28px}.menu-toggle{padding:9px;min-width:38px}.menu-toggle>span{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.founder-grid{grid-template-columns:1fr}.founder-card{flex-direction:row;align-items:center}}

'use strict';
(() => {
  const $ = (s) => document.querySelector(s);
  const all = (s) => [...document.querySelectorAll(s)];
  const input = $('#portion-count');
  const format = (n) => Number(n.toFixed(3)).toLocaleString('nl-NL',{maximumFractionDigits:3});
  const rows = [
    {name:'Rundvlees',per:.18,unit:'kg',stock:4,pack:2,packName:'bak',supplier:'Keukenpartner',recipe:'180 g'},
    {name:'Briochebroodjes',per:1,unit:'st',stock:12,pack:8,packName:'zak',supplier:'Keukenpartner',recipe:'1 st'},
    {name:'Tomaten',per:.04,unit:'kg',stock:6,pack:3,packName:'kist',supplier:'Groen & Vers',recipe:'40 g'},
    {name:'Sla',per:.03,unit:'kg',stock:1,pack:.5,packName:'zak',supplier:'Groen & Vers',recipe:'30 g'},
    {name:'Burgersaus',per:.025,unit:'l',stock:1,pack:1,packName:'fles',supplier:'Keukenpartner',recipe:'25 ml'},
    {name:'Friet',per:.15,unit:'kg',stock:6,pack:2.5,packName:'zak',supplier:'Keukenpartner',recipe:'150 g'}
  ];
  let portions=32,view='recept',completed=new Set(),tourTimer=null,tourStarted=0,tourElapsed=0,tourStep=-1,tourTouched=false;
  const tourLength=22000;
  const calc=(n)=>rows.map(r=>{const need=+(n*r.per).toFixed(4),shortage=Math.max(0,+(need-r.stock).toFixed(4)),packs=Math.ceil((shortage-1e-9)/r.pack);return {...r,need,shortage,packs:Math.max(0,packs),order:+(Math.max(0,packs)*r.pack).toFixed(4)};});
  function render(){
    const data=calc(portions);
    all('.portions-label').forEach(el=>el.textContent=`${portions} porties`);
    $('#recipe-table').innerHTML='<table class="product-table"><thead><tr><th scope="col">Product</th><th scope="col">Per portie</th><th scope="col">Nodig</th></tr></thead><tbody>'+data.map(r=>`<tr><td>${r.name}</td><td class="product-per">${r.recipe}</td><td>${format(r.need)} ${r.unit}</td></tr>`).join('')+'</tbody></table>';
    $('#stock-table').innerHTML='<table class="product-table"><thead><tr><th scope="col">Product</th><th scope="col">In huis</th><th scope="col">Tekort</th></tr></thead><tbody>'+data.map(r=>`<tr><td>${r.name}</td><td class="product-per">${format(r.stock)} ${r.unit}</td><td>${r.shortage?format(r.shortage)+' '+r.unit:'Voldoende'}</td></tr>`).join('')+'</tbody></table>';
    const mep=[['burgers','Burgers vormen',`${format(portions*.18)} kg rundvlees`,`${portions} st`],['groenten','Groenten snijden',`${format(portions*.04)} kg tomaten · ${format(portions*.03)} kg sla`,`${portions} porties`],['friet','Friet portioneren','Klaarzetten voor de service',`${format(portions*.15)} kg`]];
    $('#mep-list').innerHTML=mep.map(([id,title,detail,amount])=>`<label class="mep-row"><input type="checkbox" data-task="${id}" ${completed.has(id)?'checked':''}><span>${title}<small>${detail}</small></span><b>${amount}</b></label>`).join('');
    const orders=data.filter(r=>r.order>0);
    $('#order-count').textContent=`${orders.length} producten`;
    $('#order-list').innerHTML=orders.length?['Keukenpartner','Groen & Vers'].map(s=>{const group=orders.filter(r=>r.supplier===s);return group.length?`<h4 class="supplier-heading">${s} · voorbeeldleverancier</h4>`+group.map(r=>`<div class="order-row"><div>${r.name}<small>${format(r.need)} nodig − ${format(r.stock)} in huis = ${format(r.shortage)} ${r.unit} tekort</small></div><strong>${format(r.order)} ${r.unit}<small>${r.packs} × ${format(r.pack)} ${r.unit}</small></strong></div>`).join(''):'';}).join(''):'<p class="order-empty">Alles is op voorraad. Je hoeft niets aan te vullen.</p>';
    $('#result-summary').textContent=`${portions} porties · ${orders.length} producten aanvullen`;
    $('#portion-less').disabled=portions<=1;
    $('#portion-more').disabled=portions>=500;
  }
  function setView(next,focus=false){
    if(!['recept','mep','voorraad','bestellen'].includes(next))return;
    view=next;
    all('[data-view]').forEach(button=>{const active=button.dataset.view===view;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});
    all('.product-pane').forEach(p=>p.hidden=p.id!==`pane-${view}`);
    if(focus)$(`#tab-${view}`).focus();
  }
  function valid(){const raw=input.value.trim(),n=Number(raw);return raw!==''&&Number.isInteger(n)&&n>=1&&n<=500;}
  function update(n){portions=n;input.value=String(n);input.removeAttribute('aria-invalid');$('#quantity-error').hidden=true;completed.clear();render();}
  function stopTour(reset=false){if(tourTimer)clearInterval(tourTimer);tourTimer=null;$('#tour-button').setAttribute('aria-pressed','false');$('#tour-label').textContent=reset?'Bekijk de producttour':'Tour hervatten';$('#tour-button use').setAttribute('href','assets/icons.svg#play');if(reset){tourElapsed=0;tourStep=-1;tourTouched=false;$('#tour-progress').style.width='0%';$('#tour-status').textContent='Van planning naar bestellijst';}}
  function manual(){if(tourTouched)stopTour(true);}
  input.addEventListener('input',()=>{manual();if(valid())update(Number(input.value));else{$('#quantity-error').textContent='Vul een heel aantal van 1 tot en met 500 in.';$('#quantity-error').hidden=false;input.setAttribute('aria-invalid','true');$('#portion-less').disabled=false;$('#portion-more').disabled=false;}});
  $('#portion-less').addEventListener('click',()=>{manual();update(Math.max(1,Math.min(500,valid()?Number(input.value)-1:Math.floor(Number(input.value)||portions))));});
  $('#portion-more').addEventListener('click',()=>{manual();update(Math.min(500,Math.max(1,valid()?Number(input.value)+1:Math.ceil(Number(input.value)||portions))));});
  all('[data-view]').forEach(button=>{button.addEventListener('click',()=>{manual();setView(button.dataset.view);});button.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();manual();const list=['recept','mep','voorraad','bestellen'];let i=list.indexOf(view);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;setView(list[i],true);});});
  $('#mep-list').addEventListener('change',event=>{if(!event.target.matches('[data-task]'))return;manual();const id=event.target.dataset.task;event.target.checked?completed.add(id):completed.delete(id);});
  all('[data-open-view]').forEach(link=>link.addEventListener('click',()=>{manual();setView(link.dataset.openView);}));
  function runTour(){
    const elapsed=tourElapsed+performance.now()-tourStarted;
    $('#tour-progress').style.width=`${Math.min(100,elapsed/tourLength*100)}%`;
    const step=elapsed<3500?0:elapsed<7500?1:elapsed<12000?2:elapsed<16500?3:4;
    if(step!==tourStep){tourStep=step;const count=step===0?32:48;if(portions!==count||!valid())update(count);setView(['recept','recept','mep','voorraad','bestellen'][step]);$('#tour-status').textContent=['1/4 · Begin bij je gerecht','1/4 · Van 32 naar 48 porties','2/4 · Je voorbereiding rekent mee','3/4 · Je voorraad gaat eraf','4/4 · Je bestellijst staat klaar'][step];}
    if(elapsed>=tourLength){stopTour(false);tourElapsed=0;tourStep=-1;$('#tour-label').textContent='Bekijk de tour opnieuw';$('#tour-status').textContent='48 porties. Eén samenhangende planning.';$('#tour-progress').style.width='100%';}
  }
  $('#tour-button').addEventListener('click',()=>{if(tourTimer){tourElapsed+=performance.now()-tourStarted;stopTour(false);$('#tour-status').textContent='Gepauzeerd';return;}tourTouched=true;tourStep=-1;tourStarted=performance.now();$('#tour-button').setAttribute('aria-pressed','true');$('#tour-label').textContent='Tour pauzeren';$('#tour-button use').setAttribute('href','assets/icons.svg#pause');tourTimer=setInterval(runTour,150);runTour();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&tourTimer){tourElapsed+=performance.now()-tourStarted;stopTour(false);$('#tour-status').textContent='Gepauzeerd';}});
  const menu=$('.menu-toggle'),nav=$('#site-navigation');
  function closeMenu(){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');}
  menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
  nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
  document.addEventListener('click',e=>{if(menu.getAttribute('aria-expanded')==='true'&&!e.target.closest('.site-header'))closeMenu();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
  render();
})();
